    /**
     * Code Insee
     */
    code_insee?: string | null;
    /**
     * Adresse
     */
    adresse?: string | null;
    /**
     * Complement Adresse
     */
    complement_adresse?: string | null;
    /**
     * Longitude
     */
    longitude?: number | null;
    /**
     * Latitude
     */
